import{_ as i,C as o,o as c,c as s,j as t,a as d,E as a,ag as l}from"./chunks/framework.HG0H2VLS.js";const w=JSON.parse('{"title":"AttendeeCard","description":"","frontmatter":{},"headers":[],"relativePath":"components/attendee-card.md","filePath":"components/attendee-card.md"}'),h={name:"components/attendee-card.md"},g={id:"attendeecard",tabindex:"-1"};function p(m,e,b,u,f,x){const r=o("Badge"),n=o("ComponentDemo");return c(),s("div",null,[e[3]||(e[3]=t("hr",null,null,-1)),e[4]||(e[4]=t("h2",{id:"title-attendeecard",tabindex:"-1"},[d("title: AttendeeCard "),t("a",{class:"header-anchor",href:"#title-attendeecard","aria-label":'Permalink to "title: AttendeeCard"'},"​")],-1)),t("h1",g,[e[0]||(e[0]=d("AttendeeCard ",-1)),a(r,{type:"info",text:"Design System"}),e[1]||(e[1]=d()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#attendeecard","aria-label":'Permalink to "AttendeeCard <Badge type="info" text="Design System" />"'},"​",-1))]),e[5]||(e[5]=t("blockquote",null,[t("p",null,"Seating Planner attendee row (Unassigned tray, Table Detail)")],-1)),a(n,{src:"/demos/src/components/AttendeeCard/AttendeeCard.html"}),e[6]||(e[6]=l('<h2 id="variant-matrix-12-variants" tabindex="-1">Variant matrix (12 variants) <a class="header-anchor" href="#variant-matrix-12-variants" aria-label="Permalink to &quot;Variant matrix (12 variants)&quot;">​</a></h2><p>Axes are <strong>Type × State × Tier</strong>. Tier is single-valued (<code>Component</code>) and produces no CSS.</p><table tabindex="0"><thead><tr><th>Type</th><th>State</th><th>Node</th><th>CSS</th></tr></thead><tbody><tr><td>Attendee</td><td>Default</td><td><code>3474:89287</code></td><td><code>.attendee-card.attendee-card--attendee</code></td></tr><tr><td>Attendee</td><td>Dragged Over</td><td><code>3474:89315</code></td><td><code>+ .attendee-card--dragged-over</code></td></tr><tr><td>VIP</td><td>Default</td><td><code>3474:89290</code></td><td><code>.attendee-card--vip</code></td></tr><tr><td>VIP</td><td>Dragged Over</td><td><code>3474:89359</code></td><td><code>+ .attendee-card--dragged-over</code></td></tr><tr><td>Speaker</td><td>Default</td><td><code>3474:89286</code></td><td><code>.attendee-card--speaker</code></td></tr><tr><td>Speaker</td><td>Dragged Over</td><td><code>3474:89337</code></td><td><code>+ .attendee-card--dragged-over</code></td></tr><tr><td>Sponsor</td><td>Default</td><td><code>3474:89288</code></td><td><code>.attendee-card--sponsor</code></td></tr><tr><td>Sponsor</td><td>Dragged Over</td><td><code>3474:89381</code></td><td><code>+ .attendee-card--dragged-over</code></td></tr><tr><td>Host</td><td>Default</td><td><code>3474:89289</code></td><td><code>.attendee-card--host</code></td></tr><tr><td>Host</td><td>Dragged Over</td><td><code>3474:89293</code></td><td><code>+ .attendee-card--dragged-over</code></td></tr><tr><td>Empty</td><td>Default</td><td><code>3474:89291</code></td><td><code>.attendee-card--empty</code></td></tr><tr><td>Empty</td><td>Dragged Over</td><td><code>3528:102567</code></td><td><code>.attendee-card--empty.attendee-card--dragged-over</code></td></tr></tbody></table><p>The five filled types are 50px tall (content-driven); Empty is 48px via <code>min-block-size: var(--ai-spacing-9)</code>.</p><blockquote><p><strong>Figma fix outstanding.</strong> <code>3528:102567</code> was added on 2026-08-25 to fill the missing Empty / Dragged Over combination, but its <code>State</code> property still reads <strong><code>Default</code></strong>, so it currently collides with <code>3474:89291</code> — two variants share the same property key. The visual is unambiguously the Dragged Over treatment (solid brand border, matching the other five), and the designer confirmed that is what was added, so it is built as Empty / Dragged Over. Set <code>3528:102567</code>&#39;s State to <code>Dragged Over</code> in Figma and this note can go.</p></blockquote><h3 id="booleans" tabindex="-1">Booleans <a class="header-anchor" href="#booleans" aria-label="Permalink to &quot;Booleans&quot;">​</a></h3><p><code>Show Actions</code> and <code>Show Seat Number</code> are Figma booleans — omit <code>.attendee-card__actions</code> or <code>.attendee-card__seat</code> respectively. Both shown in the demo.</p><h2 id="interaction-model" tabindex="-1">Interaction model <a class="header-anchor" href="#interaction-model" aria-label="Permalink to &quot;Interaction model&quot;">​</a></h2><p>Confirmed with the designer 2026-08-25:</p><ul><li><strong>Drop target only.</strong> The card never initiates a drag. <code>--dragged-over</code> is a class the parent module toggles while an attendee is held over the card. No drag JS belongs here.</li><li>Delete and reorder are rendered as real <code>&lt;button&gt;</code>s with <code>aria-label</code>s. Design context conveys visual structure only, never interaction, so the frames Figma draws are buttons in code.</li></ul><h2 id="colour-model" tabindex="-1">Colour model <a class="header-anchor" href="#colour-model" aria-label="Permalink to &quot;Colour model&quot;">​</a></h2><p>The accent bar and the role label share one custom property, <code>--attendee-card-role</code>, the same pattern as TableType. Defaults bind the Seating Planner tokens:</p><table tabindex="0"><thead><tr><th>Modifier</th><th>Token</th></tr></thead><tbody><tr><td><code>--attendee</code></td><td><code>--sp-attendee</code></td></tr><tr><td><code>--vip</code></td><td><code>--sp-vip</code></td></tr><tr><td><code>--speaker</code></td><td><code>--sp-speaker</code></td></tr><tr><td><code>--sponsor</code></td><td><code>--sp-sponsor</code></td></tr><tr><td><code>--host</code></td><td><code>--sp-host</code></td></tr><tr><td><code>--empty</code></td><td><code>--ai-surface-contrast</code> (neutral, not a role colour)</td></tr></tbody></table><p><strong>Radix Vivid is the default palette</strong> at <code>:root</code>, so the card renders correctly with no extra markup. Add <code>data-seating=&quot;muted&quot;</code> or <code>&quot;radix-soft&quot;</code> to an ancestor to switch. All three are shown at the foot of the demo page.</p><h2 id="state-deltas" tabindex="-1">State deltas <a class="header-anchor" href="#state-deltas" aria-label="Permalink to &quot;State deltas&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Background</th><th>Border</th></tr></thead><tbody><tr><td>filled · Default</td><td><code>--ai-surface-primary</code></td><td>1px solid <code>--ai-border-secondary</code></td></tr><tr><td>filled · Dragged Over</td><td><code>--ai-surface-minimal</code></td><td>1px solid <code>--ai-border-brand</code></td></tr><tr><td>Empty · Default</td><td><code>--ai-surface-minimal</code></td><td>1px <strong>dashed</strong> <code>--ai-btn-secondary-border</code></td></tr><tr><td>Empty · Dragged Over</td><td><code>--ai-surface-minimal</code></td><td>1px <strong>solid</strong> <code>--ai-border-brand</code></td></tr></tbody></table><p>Empty&#39;s background is already <code>minimal</code>, so only its border changes — dashed grey to solid brand.</p><h2 id="token-mapping" tabindex="-1">Token mapping <a class="header-anchor" href="#token-mapping" aria-label="Permalink to &quot;Token mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma</th><th>CSS</th><th>Role</th></tr></thead><tbody><tr><td><code>--ai-surface-primary</code> / <code>--ai-surface-minimal</code></td><td><code>background-color</code></td><td>per state</td></tr><tr><td><code>--ai-border-secondary</code> / <code>--ai-border-brand</code> / <code>--ai-btn-secondary-border</code></td><td><code>border-color</code></td><td>per state</td></tr><tr><td><code>--ai-radius-md</code></td><td>card <code>border-radius</code></td><td></td></tr><tr><td><code>light/shadow-xxs</code> → <code>--ai-shadow-xxs</code></td><td><code>box-shadow</code></td><td>the token added 2026-08-24</td></tr><tr><td><code>--ai-spacing-2</code></td><td>card <code>padding-inline</code>, accent bar width, meta gap</td><td></td></tr><tr><td><code>--ai-radius-full</code></td><td>accent bar radius</td><td></td></tr><tr><td><code>--ai-spacing-5</code></td><td>seat badge box, Empty container gap</td><td>Figma draws 18px — see below</td></tr><tr><td><code>--ai-spacing-4</code></td><td>gap before seat / body</td><td></td></tr><tr><td><code>--ai-spacing-3</code></td><td>body <code>padding-block</code></td><td></td></tr><tr><td><code>--ai-spacing-0-5</code></td><td>body gap, actions gap</td><td></td></tr><tr><td><code>--ai-spacing-6</code></td><td>action hit area</td><td>Figma draws 28px — see below</td></tr><tr><td><code>--ai-spacing-9</code></td><td>Empty <code>min-block-size</code> (48px)</td><td></td></tr><tr><td><code>--ai-spacing-px</code></td><td>role label <code>padding-block</code></td><td></td></tr><tr><td><code>--ai-icon-size-md</code></td><td>reorder column width</td><td></td></tr><tr><td><code>--ai-icon-size-xs</code></td><td>all three icons (12px)</td><td></td></tr><tr><td><code>--ai-font-title</code></td><td>name, seat, role, company</td><td></td></tr><tr><td><code>--ai-font-body</code></td><td>Empty label</td><td>inconsistent — see below</td></tr><tr><td><code>--ai-font-semibold</code> / <code>--ai-font-bold</code> / <code>--ai-font-medium</code> / <code>--ai-font-regular</code></td><td>weights</td><td></td></tr><tr><td><code>--ai-font-fixed-xs</code> / <code>-2xs</code> / <code>-4xs</code> / <code>-5xs</code></td><td>name 14 / company 12 / role 11 / seat 10</td><td></td></tr><tr><td><code>--ai-text-primary</code> / <code>--ai-text-contrast</code></td><td>text</td><td></td></tr><tr><td><code>--ai-icon-contrast</code></td><td>action icons</td><td></td></tr></tbody></table><h2 id="spacing-and-hover-the-css-deliberately-leads-figma" tabindex="-1">Spacing and hover: the CSS deliberately leads Figma <a class="header-anchor" href="#spacing-and-hover-the-css-deliberately-leads-figma" aria-label="Permalink to &quot;Spacing and hover: the CSS deliberately leads Figma&quot;">​</a></h2><p>Refined with the designer 2026-08-25 <strong>after</strong> the initial Figma-faithful build. Figma is to be updated to match, so these are intentional divergences, not drift:</p><table tabindex="0"><thead><tr><th>Element</th><th>Property</th><th>Figma</th><th>CSS now</th></tr></thead><tbody><tr><td>seat number</td><td>leading gap</td><td><code>--ai-spacing-4</code> (12px)</td><td><strong><code>--ai-spacing-3</code></strong> (8px)</td></tr><tr><td>body (name + meta)</td><td><code>gap</code></td><td><code>--ai-spacing-0-5</code> (2px)</td><td><strong>removed</strong> — name and meta sit flush</td></tr><tr><td>meta row</td><td><code>gap</code></td><td><code>--ai-spacing-2</code> (6px)</td><td><strong><code>--ai-spacing-1</code></strong> (4px)</td></tr><tr><td>actions</td><td><code>padding-inline-start</code></td><td>not set</td><td><strong><code>--ai-spacing-3</code></strong> (8px)</td></tr><tr><td>actions</td><td><code>padding-block</code></td><td>not set</td><td><strong><code>--ai-spacing-2</code></strong> (6px)</td></tr><tr><td>action button</td><td><code>:hover</code></td><td><strong>no hover state exists</strong></td><td>bg <code>--ai-surface-secondary</code>, border <code>--ai-border-secondary</code>, icon <code>--ai-icon-secondary</code></td></tr><tr><td>accent wrapper</td><td><code>inline-size</code></td><td><code>--ai-spacing-1</code> (4px)</td><td><strong>removed</strong> — shrink-wraps the 6px bar, see below</td></tr><tr><td>Empty card</td><td>container <code>gap</code></td><td><code>--ai-spacing-5</code> (16px)</td><td><strong>removed</strong> — see below</td></tr></tbody></table><blockquote><p><strong>Do not &quot;correct&quot; these back from a Figma fetch.</strong> <code>/update-components</code> and <code>/review-component</code> both re-read <code>get_design_context</code>, will see the older values and will report the CSS as wrong. It is not — Figma is the side that is behind. Delete this section once Figma catches up.</p></blockquote><h3 id="notes-on-two-of-them" tabindex="-1">Notes on two of them <a class="header-anchor" href="#notes-on-two-of-them" aria-label="Permalink to &quot;Notes on two of them&quot;">​</a></h3><p><strong>The action-button hover is entirely additive.</strong> The Figma set has no hover, focus, pressed or disabled variant for these controls. A hover was added so they read as interactive, then the designer specified the treatment: icons darken from <code>--ai-icon-contrast</code> to <code>--ai-icon-secondary</code>, with a <code>--ai-border-secondary</code> border. The button carries <code>border: 1px solid transparent</code> at rest so the hover border cannot reflow it — verified 24×24 in both states, with <code>box-sizing: border-box</code> global from <code>base.css</code>.</p><p><strong>The Empty card&#39;s container gap was wrong, not just different.</strong> It was applying 16px between <em>all four</em> children on top of the 12px margins, and — with no flex-growing child — the card&#39;s <code>justify-content: space-between</code> had free space to distribute, which pushed the seat and label toward the centre. Figma gets the same result by wrapping accent + seat + label in a <code>flex: 1 0 0</code> group; <code>__empty-label</code> now grows instead, which is the flattened equivalent. Verified: accent 27, seat 39, label 67, Assign flush to the right padding edge.</p><h2 id="token-gaps-and-dimension-decisions" tabindex="-1">Token gaps and dimension decisions <a class="header-anchor" href="#token-gaps-and-dimension-decisions" aria-label="Permalink to &quot;Token gaps and dimension decisions&quot;">​</a></h2><p>Four dimensions in Figma have no <code>--ai-*</code> token. Resolved with the designer 2026-08-25 rather than invented:</p><table tabindex="0"><thead><tr><th>Figma</th><th>Decision</th></tr></thead><tbody><tr><td>card <code>width: 288px</code></td><td><strong>Dropped.</strong> The card is fluid and fills its container (a row in the Unassigned tray / Table Detail). The demo constrains its tray to <code>--ai-size-6</code> (320px), which — less the tray&#39;s own padding and border — leaves the card near Figma&#39;s 288px.</td></tr><tr><td>seat badge <code>18px</code></td><td><strong><code>--ai-spacing-5</code></strong> (16px)</td></tr><tr><td>action hit area <code>28px</code></td><td><strong><code>--ai-spacing-6</code></strong> (24px)</td></tr><tr><td>reorder stack <code>height: 36px</code></td><td><strong>Not a fixed height</strong> — fills the available vertical space</td></tr></tbody></table><h3 id="three-deliberate-deviations" tabindex="-1">Three deliberate deviations <a class="header-anchor" href="#three-deliberate-deviations" aria-label="Permalink to &quot;Three deliberate deviations&quot;">​</a></h3><ol><li><strong>The 3px separator dot</strong> is a middot character, not Figma&#39;s 3px SVG ellipse. It is a text separator, and a character avoids an off-scale dimension with no token.</li><li><strong>The action-icon radius</strong> uses <code>--ai-radius-sm</code> (4px). Figma binds <code>--ai-spacing-2</code> (6px) — a <em>spacing</em> token used for a radius, and 6px matches no radius step (4/8/16/24/100). <strong>Worth correcting in Figma.</strong></li><li><strong>The company font-size</strong> is bound to <code>--ai-font-fixed-xxs</code>. Figma leaves it a raw <code>text-[12px]</code> while every sibling text node cites a token. The token is exactly 12px, so binding it is visually a no-op. <strong>Worth binding in Figma.</strong></li></ol><h3 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to &quot;Accessibility&quot;">​</a></h3><p>The delete and reorder controls are drawn at 28×28 and 20px wide, both well under the 44×44 touch-target minimum in CLAUDE.md §9. <strong>Built as drawn</strong> at the designer&#39;s direction 2026-08-25, with the gap recorded here for a later pass. Every control has an <code>aria-label</code>; the accent bar and separator are <code>aria-hidden</code>.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><strong>Seat badge font family is inconsistent in Figma</strong>: <code>--ai-font-title</code> on the five filled types but <code>--ai-font-body</code> on Empty, for the same element. Built as drawn (title on filled, body on Empty) so the component matches Figma, but one of the two is almost certainly unintended.</li><li><strong>The accent bar is two elements, but the wrapper is no longer sized.</strong> Figma nests a 6px rounded bar (<code>--ai-spacing-2</code>) inside a 4px-wide wrapper (<code>--ai-spacing-1</code>), so the bar&#39;s right 2px overhangs into the following gap. The wrapper&#39;s <code>inline-size</code> was removed at the designer&#39;s direction, so it shrink-wraps the bar and the accent occupies its full 6px with no overhang — everything after it sits 2px further right (seat now starts at 21px, was 19px). The wrapper is still a separate element because it carries the <code>padding-block</code> that insets the bar vertically from the card edges; collapsing the two would lose that.</li><li><strong>No hover, focus, pressed or disabled variants exist</strong> in the Figma set, so none are implemented beyond a hover on the action buttons (needed for them to read as interactive).</li><li><strong>No dark-mode variant</strong> in Figma. The card uses theme-aware surface and border tokens throughout, so it will re-resolve under <code>[data-theme=&quot;dark&quot;]</code> — but that has not been designed or reviewed. The <code>--sp-*</code> role colours are <strong>not</strong> theme-aware.</li><li><strong><code>--ai-shadow-xxs</code> validated here.</strong> Figma binds <code>light/shadow-xxs</code> on this card, which is the token added 2026-08-24 — this is its first real consumer.</li></ul><h2 id="figma" tabindex="-1">Figma <a class="header-anchor" href="#figma" aria-label="Permalink to &quot;Figma&quot;">​</a></h2><p><a href="https://www.figma.com/design/Lus07xi8pPXLN87sQIyrEt/Affino-AI---Design-System?node-id=3474-89292" target="_blank" rel="noreferrer">Open in Figma</a></p>',37))])}const v=i(h,[["render",p]]);export{w as __pageData,v as default};
